import {
  ImageBackground,
  StyleSheet,
  Text,
  View,
  ScrollView,
} from "react-native";
import { useState, useEffect } from "react";
import { useNavigation } from "@react-navigation/native";

const HomeScreen1 = () => {
  const navigation = useNavigation();
  const image = {
    uri: "https://firebasestorage.googleapis.com/v0/b/swapper-stu.appspot.com/o/Assets%2Fproducts-banner-image.png?alt=media&token=bfe79d05-c67c-4bf2-98f7-3dd80e1c1829",
  };

  //Funciones para animar texto
  const [loopNum, setLoopNum] = useState(0);
  const [isDeleting, setIsDeleting] = useState(false);
  const [text, setText] = useState("");
  const [delta, setDelta] = useState(300 - Math.random() * 100);
  const [index, setIndex] = useState(1);
  const toRotate = ["Intercambia", "Ahorra", "Recicla", "Cambia", "Adquiere", "Ofrece", "Encuentra"];
  const period = 1000;

  useEffect(() => {
    let ticker = setInterval(() => {
      tick();
    }, delta);

    return () => {
      clearInterval(ticker);
    };
  }, [text]);

  const tick = () => {
    let i = loopNum % toRotate.length;
    let fullText = toRotate[i];
    let updatedText = isDeleting
      ? fullText.substring(0, text.length - 1)
      : fullText.substring(0, text.length + 1);

    setText(updatedText);

    if (isDeleting) {
      setDelta((prevDelta) => prevDelta / 2);
    }

    if (!isDeleting && updatedText === fullText) {
      setIsDeleting(true);
      setIndex((prevIndex) => prevIndex - 1);
      setDelta(period);
    } else if (isDeleting && updatedText === "") {
      setIsDeleting(false);
      setLoopNum(loopNum + 1);
      setIndex(1);
      setDelta(100);
    } else {
      setIndex((prevIndex) => prevIndex + 1);
    }
  };

  return (
    <View className="flex-1">
      <ScrollView>
        <ImageBackground source={image} resizeMode="cover" style={styles.image} className="h-screen">
          <View>
            <Text style={styles.text}>
              Lo que necesitas para tus estudios en un solo lugar
            </Text>
            <Text style={styles.text2}>{text}</Text>
          </View>
        </ImageBackground>
      </ScrollView>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  image: {
    flex: 1,
    justifyContent: "center",
    backgroundPosition: "left",
  },
  text: {
    width: "100%",
    color: "black",
    fontSize: 70,
    lineHeight: 84,
    fontWeight: "bold",
    paddingTop: 70,
    maxWidth: 500,
    padding: 20,
  },
  text2: {
    width: "100%",
    color: "#DDD",
    fontSize: 30,
    paddingLeft: 20,
  },
});

export default HomeScreen1;
